// Fixed builtin-modulepath diagnostic inverse; every earlier sealed map remains unchanged.
// Only this historical manifest comparison reverses the new fixture pin; its live driver/worker pin checks remain current.
function restoreBuiltinFixtureManifest(text){const map=JSON.parse(readFileSync(new URL('../../../terminal-builtin-modulepath-diagnostic-20261012/builtin-source-delta.json',import.meta.url),'utf8'));const rows=map.replacements.filter(r=>r.path==='desktop/tests/native/terminal-fresh-runtime-provision-inputs.json'&&JSON.parse(r.before).path==='desktop/tests/native/terminal-resolution-observation.mjs');assert.equal(rows.length,1);const row=rows[0];assert.equal(text.split(row.after).length,2);return text.replace(row.after,row.before);}
function restoreBuiltinModulePath(text,path){const map=JSON.parse(readFileSync(new URL('../../../terminal-builtin-modulepath-diagnostic-20261012/builtin-source-delta.json',import.meta.url),'utf8'));for(const row of map.replacements.filter(r=>r.path===path).reverse()){assert.equal(text.split(row.after).length,2,'Exact builtin-modulepath diagnostic delta '+path);text=text.replace(row.after,row.before);}return text;}

